class MemoryOrderRepository {
  orders = [];

  async add(order) {
    const saved = { ...order, id: this.orders.length + 1 };
    this.orders.push(saved);
    return saved;
  }

  async listFor(userId) {
    return this.orders.filter((order) => order.userId === userId);
  }
}

