class OrderService {
  constructor(books, maxQuantity) {
    this.books = books;
    this.maxQuantity = maxQuantity;
  }

  async place(bookId, quantity) {
    if (quantity > this.maxQuantity) throw new Error("too_many");
    const book = await this.books.find(bookId);
    if (book === undefined) throw new Error("no_such_book");
    return book.priceCents * quantity;
  }
}

