class OrderController {
  constructor(service) {
    this.service = service;
  }

  async place(request) {
    if (request.userId === undefined) return { status: 401 };
    const quantity = request.body?.quantity;
    if (!Number.isSafeInteger(quantity) || quantity < 1) return { status: 400 };
